import { Species } from "./enums/pokemon-species";
import { EggGroups } from "./enums/egg-groups";
import { Pokemon } from "./enums/pokemon";
import { GrowthRates } from "./enums/growth-rates";
import { speciesFlavorTexts } from "./texts/speciesTexts";

export class PokemonSpecies {
    constructor(
        public readonly id: Species,              // Unique Species ID
        public readonly name: string,             // Name of the Pokémon species
        public readonly baseHappiness: number | null,    // Base happiness value
        public readonly captureRate: number,      // Capture rate (out of 255)
        public readonly eggGroups: EggGroups[],   // Egg groups
        public readonly evolvesFrom: Species | null, // Evolution pre-form
        public readonly formsSwitchable: boolean, // Can the Pokémon change forms?
        public readonly genderRate: number,       // Gender ratio (Female %)
        public readonly genera: string,           // Pokémon species category
        public readonly generation: number,       // Generation introduced
        public readonly growthRate: GrowthRates,  // Growth rate category
        public readonly hasGenderDifferences: boolean, // Gender differences?
        public readonly hatchCounter: number | null,     // Steps to hatch an egg
        public readonly isBaby: boolean,          // Is it a baby Pokémon?
        public readonly isLegendary: boolean,     // Is it legendary?
        public readonly isMythical: boolean,      // Is it mythical?
        public readonly varieties: Pokemon[],     // Different forms of this species
    ) {}

    /** Check if this Pokémon species is in a specific egg group */
    isInEggGroup(group: EggGroups): boolean {
        return this.eggGroups.includes(group);
    }

    /** Get a readable gender ratio */
    getGenderRatio(): string {
        if (this.genderRate === -1) return "Genderless";
        const malePercent = ((8 - this.genderRate) / 8) * 100;
        const femalePercent = (this.genderRate / 8) * 100;
        return `${malePercent}% Male / ${femalePercent}% Female`;
    }

    /** Get entry by id */
    getEntryById(id: number): string {
        return speciesFlavorTexts[this.id][id];
    }
}

